Q: Reliable way of getting data continuously from UDP connection in iOS Swift A: <p>Hello Every one I have done some research and found a reliable solution regarding this.</p>
<p>As I learn more about UDP I realize in UDP the listning and sending of data can be implemented independently so, below code I have used for contineouslly listning for the data hope this will help out. If needed I can also provide the working code for sending data in UDP. but my question is not abut sending data so for this question I am not adding that.</p>
<pre><code>import Foundation

final class UdpListenerManager {

    private var socketFD: Int32 = -1
    private var isListening = false
    private let queue = DispatchQueue(label: &quot;udp.listener.queue&quot;, qos: .background)
    private var currentTelemetry = TelemetryData()
    private var receiveBuffer = Data()

    var onTelemetryUpdate: ((TelemetryData) -&gt; Void)?
    var onDataReceived: ((Data, sockaddr_in) -&gt; Void)?

    func startListening(on port: UInt16) {
        guard !isListening else { return }
        isListening = true

        queue.async { [weak self] in
            self?.setupSocketAndListen(port: port)
        }
    }

    func stopListening() {
        isListening = false

        if socketFD &gt;= 0 {
            close(socketFD)
            socketFD = -1
        }
    }

    deinit {
        stopListening()
    }

    private func setupSocketAndListen(port: UInt16) {
        socketFD = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)
        guard socketFD &gt;= 0 else {
            print(&quot;Failed to create UDP socket&quot;)
            return
        }

        var reuse: Int32 = 1
        setsockopt(
            socketFD,
            SOL_SOCKET,
            SO_REUSEADDR,
            &amp;reuse,
            socklen_t(MemoryLayout.size(ofValue: reuse))
        )

        var addr = sockaddr_in()
        addr.sin_family = sa_family_t(AF_INET)
        addr.sin_port = port.bigEndian
        addr.sin_addr = in_addr(s_addr: INADDR_ANY)

        let bindResult = withUnsafePointer(to: &amp;addr) {
            $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                bind(socketFD, $0, socklen_t(MemoryLayout&lt;sockaddr_in&gt;.size))
            }
        }

        guard bindResult == 0 else {
            print(&quot;Bind failed on port \(port)&quot;)
            close(socketFD)
            socketFD = -1
            return
        }

        print(&quot;UDP listening on port \(port)&quot;)
        receiveLoop()
    }

    private func receiveLoop() {
        while isListening {
            var buffer = [UInt8](repeating: 0, count: 2048)
            var sourceAddr = sockaddr_in()
            var addrLen: socklen_t = socklen_t(MemoryLayout&lt;sockaddr_in&gt;.size)

            let receivedBytes = withUnsafeMutablePointer(to: &amp;sourceAddr) {
                $0.withMemoryRebound(to: sockaddr.self, capacity: 1) {
                    recvfrom(
                        socketFD,
                        &amp;buffer,
                        buffer.count,
                        0,
                        $0,
                        &amp;addrLen
                    )
                }
            }

            guard receivedBytes &gt; 0 else {
                if isListening {
                    print(&quot;⚠️ recvfrom failed&quot;)
                }
                continue
            }

            let data = Data(buffer.prefix(receivedBytes))

            // Original raw callback
            onDataReceived?(data, sourceAddr)

            // Logic to decode and return telemetry data
            decodeMavlink(data)
        }
    }

    private func decodeMavlink(_ data: Data) {
        //do the decoding of the data according to your need
    }

    private func bytesToFloat(_ b: [UInt8], _ o: Int) -&gt; Float {
        let u = UInt32(b[o]) | (UInt32(b[o+1]) &lt;&lt; 8) | (UInt32(b[o+2]) &lt;&lt; 16) | (UInt32(b[o+3]) &lt;&lt; 24)
        return Float(bitPattern: u)
    }
}

</code></pre>

Q: Rounding up to the nearest multiple of a number A: <p>This works when factor will always be positive:</p>
<pre><code>int round_up(int num, int factor)
{
    return num + factor - 1 - (num + factor - 1) % factor;
}
</code></pre>
<p>Edit: Updated to return eg: <code>round_up(0,100)=0</code> instead of <code>round_up(0,100)=100</code>.</p>
